def determine_winner(n):
    # Check if Vanya can win in his first move
    if (n + 1) % 3 == 0 or (n - 1) % 3 == 0:
        return "First"

    # Otherwise, simulate the game for up to 10 moves
    # Vanya starts, and players alternate
    # After 10 moves, Vova wins
    # Since both play optimally, we can use the following logic:
    # If the remainder of n modulo 3 is 0, then Vova can always win
    # Else, Vanya can win in some future move
    if n % 3 == 0:
        return "Second"
    else:
        return "First"

