def buy_two_chocolates(prices, money):
    prices.sort()
    min_sum = float('inf')
    n = len(prices)
    for i in range(n - 1):
        for j in range(i + 1, n):
            total = prices[i] + prices[j]
            if total <= money:
                min_sum = min(min_sum, total)
    if min_sum == float('inf'):
        return money
    return money - min_sum

def process_queries(n, queries):
    nums = [0] * n
    count = 0
    result = []

    for index, color in queries:
        prev_color = nums[index]

        # Remove contributions from previous color
        if prev_color != 0:
            # Check left neighbor
            if index > 0 and nums[index - 1] == prev_color:
                count -= 1
            # Check right neighbor
            if index < n - 1 and nums[index + 1] == prev_color:
                count -= 1

        # Update the color
        nums[index] = color

        # Add contributions from new color
        if color != 0:
            # Check left neighbor
            if index > 0 and nums[index - 1] == color:
                count += 1
            # Check right neighbor
            if index < n - 1 and nums[index + 1] == color:
                count += 1

        result.append(count)

    return result

