def max_alternating_subarray_length(nums):
    max_len = -1
    n = len(nums)

    for i in range(n - 1):
        current_len = 1  # Start with the first element
        j = i + 1
        # Check if the next element satisfies s_1 = s_0 + 1
        if nums[j] == nums[i] + 1:
            current_len += 1
            # Continue checking the alternating pattern
            while j + 1 < n:
                if nums[j + 1] == nums[j] - 1:
