def find_min_string(a, b, c):
    from itertools import permutations

    def merge(s1, s2):
        # Find the maximum overlap between s1 and s2
        max_overlap = 0
        for i in range(1, min(len(s1), len(s2)) + 1):
            if s1[-i:] == s2[:i]:
                max_overlap = i
        return s1 + s2[max_overlap:]

    def combine_order(order):
        # Combine the strings in the given order
        result = order[0]
        for i in range(1, len(order)):
            result = merge(result, order[i])
        return result

    # Generate all permutations of the three strings
    min_str = None
    for perm in permutations([a, b, c]):
        combined = combine_order(perm)
        if min_str is None or len(combined) < len(min_str) or (len(combined) == len(min_str) and combined < min_str):
            min_str = combined

    return min_str

def can_reduce_to_zero(nums, k):
    n = len(nums)
    total_sum = sum(nums)
    if total_sum % k != 0:
        return False

    ops = 0
    for i in range(n - k + 1):
        # Apply the required number of operations to nums[i]
        ops += nums[i]
        # Subtract the operations from the current and next k-1 elements
        for j in range(i, i + k):
            nums[j] -= ops
        # If any element becomes negative, it's invalid
        if nums[i] < 0:
            return False
    # After processing all positions, check if all elements are zero
    return all(x == 0 for x in nums)

