def min_operations_to_remove_almost_equal(word):
    n = len(word)
    if n < 2:
        return 0

    operations = 0
    for i in range(1, n):
        # Check if current and previous characters are almost-equal
        prev_char = word[i - 1]
        curr_char = word[i]

        if abs(ord(curr_char) - ord(prev_char)) <= 1:
            # Need to change the current character
            operations += 1
            # Choose a character that is not almost-equal to the previous or next character
            # We'll choose 'a' as a default replacement unless it conflicts with the next character
            new_char = 'a'
            if i + 1 < n:
                next_char = word[i + 1]
                while abs(ord(new_char) - ord(prev_char)) <= 1 or abs(ord(new_char) - ord(next_char)) <= 1:
