def can_sort_array(nums):
    # Calculate the number of set bits for each number
    set_bits = [bin(num).count('1') for num in nums]

    # Create a list of groups based on the set bit count
    groups = {}
    for i, bit_count in enumerate(set_bits):
        if bit_count not in groups:
            groups[bit_count] = []
        groups[bit_count].append(i)

    # Sort the original array and create a target array
    sorted_nums = sorted(nums)

    # Check if the elements in each group can be rearranged to match the sorted array
    for bit_count, indices in groups.items():
        # Extract the elements in the current group from both the original and sorted arrays
        original_group = [nums[i] for i in indices]
        sorted_group = [sorted_nums[i] for i in indices]

        # Sort both groups and compare
        if sorted(original_group) != sorted(sorted_group):
            return False

    return True

