def generate_grid(N, R, C):
    from itertools import permutations

    # Create an empty grid
    grid = [['.' for _ in range(N)] for _ in range(N)]

    # Try all possible placements for each row
    for row in range(N):
        # Get the required first character for this row
        first_char = R[row]

        # Generate all permutations of positions for A, B, C in this row
        for perm in permutations(range(N)):
            # Check if the first character matches the required one
            if grid[row][perm[0]] != '.' or grid[row][perm[0]] != first_char:
                continue

            # Place A, B, C at the positions given by the permutation
            for i, char in enumerate(['A', 'B', 'C']):
                grid[row][perm[i]] = char

            # Now check if the column constraints are satisfied
            valid = True
            for col in range(N):
                # Count how many times each character appears in the column
                count = {'A': 0, 'B': 0, 'C': 0}
                for r in range(N):
                    if grid[r][col] == '.':
                        continue
                    count[grid[r][col]] += 1

                # If any character appears more than once, it's invalid
                if any(count[char] > 1 for char in ['A', 'B', 'C']):
                    valid = False
                    break

            if valid:
                # If the grid is valid, return it
                return "Yes\n" + "\n".join("".join(row) for row in grid)

    # If no valid configuration is found
    return "No"

