def replace_question_marks(s):
    from collections import defaultdict

    freq = defaultdict(int)
    result = []

    for ch in s:
        if ch != '?':
            freq[ch] += 1
            result.append(ch)
        else:
            # Find the character with the minimum frequency
            min_freq = float('inf')
            candidates = []
            for c in 'abcdefghijklmnopqrstuvwxyz':
                if freq[c] < min_freq:
                    min_freq = freq[c]
                    candidates = [c]
                elif freq[c] == min_freq:
                    candidates.append(c)
            # Choose the lexicographically smallest candidate
            chosen_char = min(candidates)
            freq[chosen_char] += 1
            result.append(chosen_char)

    return ''.join(result)

