        # Option 1: Go down if possible and not consecutive
        if not last_operation_was_down and current_stair > 0:
            total_ways += ways(current_stair - 1, jump, True)

        # Option 2: Go up
        next_stair = current_stair + (1 << jump)  # 2^jump
        total_ways += ways(next_stair, jump + 1, False)

        return total_ways

    # Start at stair 1, initial jump is 0, and no previous operation
    return ways(1, 0, False)

def min_balanced_partitions(s):
    from collections import defaultdict

    def is_balanced(freq):
        # Get the first non-zero frequency
        first = None
        for count in freq.values():
            if count > 0:
                first = count
                break
        if first is None:
            return True  # Empty substring
        # Check if all non-zero frequencies are equal to 'first'
        for count in freq.values():
            if count != 0 and count != first:
                return False
        return True

    n = len(s)
    partitions = 0
    freq = defaultdict(int)
    for i in range(n):
        freq[s[i]] += 1
        if is_balanced(freq):
            partitions += 1
            freq = defaultdict(int)
    return partitions

