def determine_middle_brother(S_AB, S_AC, S_BC):
    # Define the relationships
    relations = {
        'AB': S_AB,
        'AC': S_AC,
        'BC': S_BC
    }

    # Determine the order of brothers based on the relations
    # We will test all possible permutations of A, B, C and check which one satisfies the constraints

    from itertools import permutations

    for order in permutations(['A', 'B', 'C']):
        # Check if the order satisfies all given relations
        valid = True
        # Check AB relation
        if relations['AB'] == '<':
            if order.index('A') >= order.index('B'):
                valid = False
        else:
            if order.index('A') <= order.index('B'):
                valid = False
        # Check AC relation
        if relations['AC'] == '<':
            if order.index('A') >= order.index('C'):
                valid = False
        else:
            if order.index('A') <= order.index('C'):
                valid = False
        # Check BC relation
        if relations['BC'] == '<':
            if order.index('B') >= order.index('C'):
                valid = False
        else:
            if order.index('B') <= order.index('C'):
                valid = False

        if valid:
            # Return the middle brother (second in the order)
            return order[1]

    return None

