def matches_pattern(s, p):
    # Split the pattern into prefix and suffix
    star_index = p.index('*')
    prefix = p[:star_index]
    suffix = p[star_index+1:]

    # Length of prefix and suffix
    len_prefix = len(prefix)
    len_suffix = len(suffix)

    # Iterate over all possible starting positions in s for the prefix
    for i in range(len(s) - len_prefix - len_suffix + 1):
        # Check if the prefix matches at position i
        if s[i:i+len_prefix] == prefix:
            # Check if the suffix matches at position i + len_prefix + len_star (len_star is 0 or more)
            for j in range(i + len_prefix, len(s) - len_suffix + 1):
                if s[j:j+len_suffix] == suffix:
                    return True
    return False

