def longest_subsequence_with_non_increasing_differences(nums):
    n = len(nums)
    dp = [{} for _ in range(n)]  # dp[i] will store {last_diff: max_length}

    max_len = 1  # At least one element in the subsequence

    for i in range(n):
        # Start with the subsequence containing only nums[i]
        dp[i][0] = 1

        for j in range(i):
            diff = abs(nums[i] - nums[j])

            # Check all possible previous differences in dp[j]
            for prev_diff in dp[j]:
                if prev_diff >= diff:
                    # Update dp[i] with the new difference and length
                    if diff in dp[i]:
                        dp[i][diff] = max(dp[i][diff], dp[j][prev_diff] + 1)
                    else:
                        dp[i][diff] = dp[j][prev_diff] + 1

            # Also consider the case where the subsequence starts at nums[j] and ends at nums[i]
            if 0 in dp[j]:
                if diff in dp[i]:
                    dp[i][diff] = max(dp[i][diff], dp[j][0] + 1)
                else:
                    dp[i][diff] = dp[j][0] + 1

        # Update the global maximum length
        for val in dp[i].values():
            max_len = max(max_len, val)

    return max_len

